#include <stdio.h>

void transfer(int *from, int *to, int amount) {
    int moved = amount < *from ? amount : *from;
    *from -= moved;
    *to += moved;
}

int main(void) {
    int a, b, t;
    scanf("%d %d %d", &a, &b, &t);
    transfer(&a, &b, t);
    printf("%d %d\n", a, b);
    return 0;
}
